#!/usr/bin/env python3
"""Merge user data from JSON, CSV and Parquet sources with A > B > C priority."""
import json
import datetime as dt

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]
OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

# canonical field -> accepted aliases (in order of preference within a source)
FIELD_ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}
FIELDS = ["name", "email", "created_date", "status"]


def load_source(path):
    if path.endswith(".json"):
        with open(path) as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            # tolerate {"users": [...]}-style payloads
            for key in ("users", "data", "records", "items"):
                if isinstance(data.get(key), list):
                    data = data[key]
                    break
        return pd.DataFrame(data)
    if path.endswith(".csv"):
        return pd.read_csv(path)
    return pd.read_parquet(path)


def normalise_frame(df, source_name):
    df = df.copy()
    df.columns = [str(c).strip() for c in df.columns]

    renames = {}
    for canon, aliases in FIELD_ALIASES.items():
        for alias in aliases:
            if alias in df.columns:
                renames[alias] = canon
                break
    df = df.rename(columns=renames)

    missing = [c for c in ["user_id"] + FIELDS if c not in df.columns]
    for col in missing:
        df[col] = None

    # keep only canonical columns
    df = df[["user_id"] + FIELDS]

    # user_id -> integer (nulls dropped)
    df["user_id"] = pd.to_numeric(df["user_id"], errors="coerce")
    df = df[df["user_id"].notna()]
    df["user_id"] = df["user_id"].astype("Int64").astype("int64")

    # dates -> YYYY-MM-DD strings
    def fmt_date(value):
        if value is None:
            return None
        if isinstance(value, float) and pd.isna(value):
            return None
        if isinstance(value, (dt.datetime, dt.date, pd.Timestamp)):
            return pd.Timestamp(value).strftime("%Y-%m-%d")
        text = str(value).strip()
        if not text or text.lower() in ("nan", "none", "null", "nat"):
            return None
        try:
            return pd.to_datetime(text, errors="raise").strftime("%Y-%m-%d")
        except Exception:
            try:
                return pd.to_datetime(text, errors="coerce").strftime("%Y-%m-%d")
            except Exception:
                return text

    df["created_date"] = df["created_date"].map(fmt_date)

    # status -> normalised lowercase string ("active"/"inactive")
    def fmt_status(value):
        if value is None:
            return None
        if isinstance(value, float) and pd.isna(value):
            return None
        if isinstance(value, bool):
            return "active" if value else "inactive"
        text = str(value).strip()
        if not text or text.lower() in ("nan", "none", "null", "nat"):
            return None
        low = text.lower()
        if low in ("true", "1", "yes", "y", "active", "enabled"):
            return "active"
        if low in ("false", "0", "no", "n", "inactive", "disabled"):
            return "inactive"
        return text

    df["status"] = df["status"].map(fmt_status)

    for col in ("name", "email"):
        df[col] = df[col].map(
            lambda v: None
            if v is None or (isinstance(v, float) and pd.isna(v))
            else str(v).strip()
        )

    df["_source"] = source_name
    return df


def main():
    frames = {}
    for name, path in SOURCES:
        frames[name] = normalise_frame(load_source(path), name)

    all_ids = sorted(
        set().union(*[set(f["user_id"].tolist()) for f in frames.values()])
    )
    priority = [name for name, _ in SOURCES]

    rows = []
    conflicts = []

    for uid in all_ids:
        per_source = {}
        for src in priority:
            f = frames[src]
            match = f[f["user_id"] == uid]
            if not match.empty:
                per_source[src] = match.iloc[0].to_dict()

        row = {"user_id": int(uid)}
        for field in FIELDS:
            present = {
                src: per_source[src][field]
                for src in priority
                if src in per_source and per_source[src].get(field) is not None
            }
            if not present:
                row[field] = None
                continue
            # highest priority non-null value wins
            selected = present[min(present, key=priority.index)]
            row[field] = selected

            distinct = {str(v) for v in present.values()}
            if len(present) > 1 and len(distinct) > 1:
                conflicts.append(
                    {
                        "user_id": int(uid),
                        "field": field,
                        "values": {k: present[k] for k in priority if k in present},
                        "selected": selected,
                    }
                )
        rows.append(row)

    merged = pd.DataFrame(rows, columns=["user_id"] + FIELDS)
    merged["user_id"] = merged["user_id"].astype("int64")

    table = pa.Table.from_pandas(
        merged,
        schema=pa.schema(
            [
                ("user_id", pa.int64()),
                ("name", pa.string()),
                ("email", pa.string()),
                ("created_date", pa.string()),
                ("status", pa.string()),
            ]
        ),
        preserve_index=False,
    )
    pq.write_table(table, OUT_PARQUET)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w") as fh:
        json.dump(report, fh, indent=2)

    print(merged.to_string())
    print("\ntotal_conflicts:", len(conflicts))
    print(json.dumps(report, indent=2)[:2000])


if __name__ == "__main__":
    main()
